function completedReportPanel(){const done=reservations.filter(x=>x.status==='COMPLETED').sort((a,b)=>b.date.localeCompare(a.date)||a.start_time.localeCompare(b.start_time));return '<div class="panel"><h2 class="h2">Rekap reservasi selesai</h2><p class="muted">Daftar ini hanya memuat pemesanan ruangan dengan status <b>Selesai</b>. File dapat dibuka langsung menggunakan Microsoft Excel.</p><div class="row" style="align-items:center;justify-content:space-between"><div><b>'+done.length+'</b> reservasi selesai</div><button class="btn" data-action="export-completed" '+(done.length?'':'disabled')+'>Unduh Excel (.csv)</button></div>'+(done.length?'<div class="tablewrap" style="margin-top:16px"><table><thead><tr><th>No.</th><th>Agenda</th><th>Pemohon</th><th>Ruang</th><th>Tanggal</th><th>Waktu</th><th>Status</th></tr></thead><tbody>'+done.map((x,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(x.title||'-')+'</td><td>'+esc(x.userName||'-')+'</td><td>'+esc(x.roomName||'-')+'</td><td>'+esc(x.date||'-')+'</td><td>'+esc(x.start_time||'-')+'–'+esc(x.end_time||'-')+'</td><td>Selesai</td></tr>').join('')+'</tbody></table></div>':'<p class="muted" style="margin-top:16px">Belum ada reservasi yang selesai.</p>')+'</div>'}
function exportCompletedReservations(){const rows=reservations.filter(x=>x.status==='COMPLETED').sort((a,b)=>b.date.localeCompare(a.date)||a.start_time.localeCompare(b.start_time));if(!rows.length){alert('Belum ada reservasi yang selesai untuk diekspor.');return}const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',lines=[['No','Agenda','Nama Pemohon','Nama Ruangan','Tanggal','Jam Mulai','Jam Selesai','Status'],...rows.map((x,i)=>[i+1,x.title||'',x.userName||'',x.roomName||'',x.date||'',x.start_time||'',x.end_time||'','Selesai'])].map(r=>r.map(q).join(';'));const blob=new Blob(['\\uFEFFsep=;\\r\\n'+lines.join('\\r\\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Rekap-Reservasi-Selesai-'+today()+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
