 await env.DB.prepare('CREATE TABLE IF NOT EXISTS app_migrations (name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)').run();
 const migration=await env.DB.prepare("SELECT name FROM app_migrations WHERE name='seed-cfh-accounts-v1'").first();
 if(!migration){
  await env.DB.batch([
   env.DB.prepare("UPDATE users SET name='admin',access_code='03',role='ADMIN',active=1 WHERE id='admin-awal'"),
   env.DB.prepare("UPDATE users SET name='SEKERTARIAT',access_code='04',role='USER',active=1 WHERE id='user-awal'"),
   env.DB.prepare("INSERT OR IGNORE INTO users(id,name,access_code,role,active) VALUES('tanaman-pangan','TANAMAN PANGAN','05','USER',1)"),
   env.DB.prepare("INSERT OR IGNORE INTO users(id,name,access_code,role,active) VALUES('hortikultura','HORTIKULTURA','06','USER',1)"),
   env.DB.prepare("INSERT OR IGNORE INTO users(id,name,access_code,role,active) VALUES('perkebunan','PERKEBUNAN','07','USER',1)"),
   env.DB.prepare("INSERT OR IGNORE INTO users(id,name,access_code,role,active) VALUES('pspf','PSPF','08','USER',1)"),
   env.DB.prepare("UPDATE users SET active=0 WHERE id NOT IN ('admin-awal','user-awal','tanaman-pangan','hortikultura','perkebunan','pspf')"),
   env.DB.prepare("INSERT INTO app_migrations(name,applied_at) VALUES('seed-cfh-accounts-v1',?)").bind(Date.now())
  ]);
 }
 const specialMigration=await env.DB.prepare("SELECT name FROM app_migrations WHERE name='seed-kepala-sekretaris-code-01-v1'").first();
