  if(p==='/api/push-subscriptions'&&m==='DELETE'){const u=need(),b=await body();if(b.endpoint)await env.DB.prepare('DELETE FROM push_subscriptions WHERE endpoint=? AND user_id=?').bind(b.endpoint,u.id).run();return reply({ok:true})}
  if(p==='/api/login'&&m==='POST'){const b=await body(),code=String(b.code||'').trim(),u=await env.DB.prepare('SELECT id,name,role FROM users WHERE access_code=? AND active=1').bind(code).first();if(!u)return reply({error:'Kode akses tidak valid.'},401);const t=crypto.randomUUID()+crypto.randomUUID();await env.DB.prepare('INSERT INTO sessions(token,user_id,expires_at) VALUES(?,?,?)').bind(t,u.id,Date.now()+43200000).run();return reply({user:u},200,{'set-cookie':'sawah_session='+t+'; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=43200'})}
