  if(p==='/api/closed-dates'&&m==='GET'){need();const r=await env.DB.prepare('SELECT date,reason FROM closed_dates ORDER BY date').all();return reply({dates:r.results})}if(p==='/api/closed-dates'&&m==='POST'){admin();const b=await body(),date=String(b.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Tanggal tidak valid.');await env.DB.prepare('INSERT INTO closed_dates(date,reason,created_at) VALUES(?,?,?) ON CONFLICT(date) DO UPDATE SET reason=excluded.reason').bind(date,String(b.reason||'').slice(0,120),Date.now()).run();return reply({ok:true})}const closedMatch=p.match(/^\/api\/closed-dates\/(\d{4}-\d{2}-\d{2})$/);if(closedMatch&&m==='DELETE'){admin();await env.DB.prepare('DELETE FROM closed_dates WHERE date=?').bind(closedMatch[1]).run();return reply({ok:true})}if(p==='/api/monitor-schedule'&&m==='GET'){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),date=parts.find(x=>x.type==='year').value+'-'+parts.find(x=>x.type==='month').value+'-'+parts.find(x=>x.type==='day').value;const r=await env.DB.prepare("SELECT r.date,r.start_time,r.end_time,r.status,rooms.name AS roomName,users.name AS bookedBy FROM reservations r JOIN rooms ON rooms.id=r.room_id JOIN users ON users.id=r.user_id WHERE r.date>=? AND r.status IN ('PENDING','APPROVED','IN_PROGRESS') ORDER BY r.date,r.start_time").bind(date).all();return reply({reservations:r.results})}
