  let q=p.match(/^\/api\/rooms\/([^/]+)$/);if(q&&m==='PATCH'){admin();const b=await body(),name=String(b.name||'').trim(),capacity=Number(b.capacity);if(!name||name.length>80)throw Error('Nama ruang wajib diisi dan maksimal 80 karakter.');if(!Number.isInteger(capacity)||capacity<1||capacity>10000)throw Error('Kapasitas harus berupa angka minimal 1.');await env.DB.prepare('UPDATE rooms SET name=?,location=?,capacity=?,facilities=? WHERE id=? AND active=1').bind(name,String(b.location||'').slice(0,160),capacity,String(b.facilities||'').slice(0,500),q[1]).run();return reply({ok:true})}if(q&&m==='DELETE'){admin();await env.DB.prepare('UPDATE rooms SET active=0 WHERE id=?').bind(q[1]).run();return reply({ok:true})}
