  q=p.match(/^\/api\/users\/([^/]+)$/);if(q&&m==='PATCH'){admin();const b=await body();if(Object.prototype.hasOwnProperty.call(b,'active'))await env.DB.prepare('UPDATE users SET active=? WHERE id=?').bind(b.active?1:0,q[1]).run();if(Object.prototype.hasOwnProperty.call(b,'name')){const name=String(b.name||'').trim();if(!name||name.length>80)throw Error('Nama wajib diisi dan maksimal 80 karakter.');await env.DB.prepare('UPDATE users SET name=? WHERE id=?').bind(name,q[1]).run()}if(Object.prototype.hasOwnProperty.call(b,'accessCode')){const code=String(b.accessCode||'').trim();if(code.length<2||code.length>32)throw Error('Kode akses minimal 2 dan maksimal 32 karakter.');const exists=await env.DB.prepare('SELECT id FROM users WHERE access_code=? AND id<>?').bind(code,q[1]).first();if(exists)throw Error('Kode akses sudah digunakan pengguna lain.');await env.DB.prepare('UPDATE users SET access_code=? WHERE id=?').bind(code,q[1]).run()}return reply({ok:true})}
